fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(2, 7);
        host::display::state_set(3, 50);
        let mut k: i32 = 0;
        while k < 48 {
            host::display::state_set(8 + k, 50);
            k = k + 1;
        }
    }
    if t % 3 == 0 {
        let seed: i32 = host::display::state_get(2) * 1103515245 + 12345;
        host::display::state_set(2, seed);
        let step: i32 = ((seed >> 16) & 15) - 7;
        let mut v: i32 = host::display::state_get(3) + step;
        if v < 5 { v = 5; }
        if v > 95 { v = 95; }
        host::display::state_set(3, v);
        let head: i32 = host::display::state_get(1);
        host::display::state_set(8 + head, v);
        host::display::state_set(1, (head + 1) % 48);
    }
    host::display::clear(0x000000);
    let head: i32 = host::display::state_get(1);
    let top: i32 = 40;
    let ch: i32 = h - 80;
    let mut i: i32 = 0;
    while i < 47 {
        let a: i32 = host::display::state_get(8 + (head + i) % 48);
        let b: i32 = host::display::state_get(8 + (head + i + 1) % 48);
        let x0: i32 = 8 + i * (w - 16) / 47;
        let x1: i32 = 8 + (i + 1) * (w - 16) / 47;
        host::display::draw_line(x0, top + ch - a * ch / 100, x1, top + ch - b * ch / 100, 0x00ff66);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "LIVE FEED", 0x808080, 1);
    host::display::draw_number(8, 20, host::display::state_get(3), 0xffffff, 2);
    host::display::present();
}
